CELLS = json.loads(r'''[{"kind":"md","source":"# S09 · Taller exprés de MongoDB Atlas Vector Search\n\n**Ya estudiaste las diapositivas 1–21. Continúa en la presentación desde [S22](https://jazaineam1.github.io/BigData2026/Presentaciones/s09-de-palabras-a-significado.html#s22).**\n\n**Objetivo en 55 minutos:** llevar textos SECOP desde Colab a una colección de MongoDB Atlas con embeddings E5, crear un índice de búsqueda vectorial y ejecutar una consulta real `$vectorSearch`.\n\n**RUTA PRINCIPAL — CELDAS 1–17 (ocho pasos ejecutables).** Instalar → muestra de datos → embeddings → conectar → persistir → crear índice → esperar estado → consultar → comparar con exacta local → exportar JSON.\n\n- **Modo demostración:** 120 documentos para obtener resultados en clase sin esperar a codificar 6.000.\n- **Modo ampliado:** hasta 6.000 documentos cuando la fuente los entregue, para continuar después.\n- **Credenciales:** no se solicita login LMS. Para **Atlas real** se necesita un cluster, conexión e IP permitida. El docente puede proyectar su conexión; no se comparte ninguna contraseña con el grupo.\n- **Respaldo:** sin Atlas, NumPy puede hacer búsqueda exacta local. **Nunca se reportará como búsqueda Atlas**.\n\n**No ejecutes el apéndice avanzado para completar la hora práctica:** permanece al final para profundizar en BM25, RRF, ortografía y CSV propios."},{"kind":"code","source":"#@title Instalar dependencias\n%pip -q install sentence-transformers==5.1.1 rank-bm25==0.2.2 pymongo==4.15.2 rapidfuzz==3.14.3"},{"kind":"md","source":"## Paso 1 · 0–12 min · Preparar documentos e identificar la fuente\n\nLa base vectorial no transforma texto por sí misma. Colab descarga o lee el CSV, valida los IDs y conserva los metadatos. **Cambia el modo** para una prueba rápida o una ampliación.\n\n**Origen:** el archivo SECOP del curso. Si la descarga falla, usa el conjunto ficticio marcado como tal; no mezcles esos datos con la evidencia SECOP. Si el CSV solo contiene menos de 6.000 procesos válidos, mostraremos el número verdadero.\n\n**Qué enseñar:** un documento vectorial conserva ID, texto y entidad además del embedding. No se pierde la posibilidad de identificar su procedencia."},{"kind":"code","source":"#@title 1 · Cargar SECOP y preparar un lote de 120 (o hasta 6000) documentos\nimport hashlib, json, os, time\nimport numpy as np\nimport pandas as pd\nfrom IPython.display import display\nMODO_DEMO = \"rápido (120)\" #@param [\"rápido (120)\", \"ampliado (6000)\", \"respaldo sintético\"]\nCSV_SECOP = \"https://raw.githubusercontent.com/jazaineam1/BigData2026/main/Datos/s06_contexto_relacional.csv\"\nMAX_FILAS = 120 if MODO_DEMO.startswith(\"rápido\") else 6000\nif MODO_DEMO == \"respaldo sintético\":\n    raw = pd.DataFrame([\n      {\"id_proceso\":\"DEMO-1\",\"nombre_proceso\":\"Mantenimiento de aeronaves KFIR\",\"descripcion\":\"Inspección y reparación de aviones militares\",\"entidad\":\"Aeronáutica\",\"url_secop\":\"\"},\n      {\"id_proceso\":\"DEMO-2\",\"nombre_proceso\":\"Licencias de software\",\"descripcion\":\"Adquisición de sistemas informáticos\",\"entidad\":\"Tecnología\",\"url_secop\":\"\"},\n      {\"id_proceso\":\"DEMO-3\",\"nombre_proceso\":\"Repuestos para helicópteros\",\"descripcion\":\"Mantenimiento y soporte de aeronaves\",\"entidad\":\"Aeronáutica\",\"url_secop\":\"\"},\n      {\"id_proceso\":\"DEMO-4\",\"nombre_proceso\":\"Conectividad de un hospital\",\"descripcion\":\"Red para atención médica\",\"entidad\":\"Salud\",\"url_secop\":\"\"},\n      {\"id_proceso\":\"DEMO-5\",\"nombre_proceso\":\"Construcción de escenario deportivo\",\"descripcion\":\"Obras para entrenamiento de atletas\",\"entidad\":\"Deporte\",\"url_secop\":\"\"},\n      {\"id_proceso\":\"DEMO-6\",\"nombre_proceso\":\"Vigilancia de edificios\",\"descripcion\":\"Servicio de seguridad de instalaciones\",\"entidad\":\"Seguridad\",\"url_secop\":\"\"},\n    ])\n    ORIGEN = \"Ejemplo sintético: no SECOP real\"\nelse:\n    raw = pd.read_csv(CSV_SECOP, dtype=str, keep_default_na=False)\n    ORIGEN = CSV_SECOP\n    required = [\"id_proceso\",\"nombre_proceso\",\"descripcion\"]\n    missing = [x for x in required if x not in raw.columns]\n    if missing:\n        raise ValueError(\"No coinciden las columnas del CSV. Faltan: \"+str(missing))\nfor colname in [\"id_proceso\",\"nombre_proceso\",\"descripcion\",\"entidad\",\"url_secop\"]:\n    if colname not in raw.columns: raw[colname] = \"\"\nraw = raw[[\"id_proceso\",\"nombre_proceso\",\"descripcion\",\"entidad\",\"url_secop\"]].fillna(\"\")\nraw[\"id_proceso\"] = raw[\"id_proceso\"].astype(str).str.strip()\nraw = raw.loc[raw.id_proceso.ne(\"\")].drop_duplicates(\"id_proceso\").copy()\nraw[\"texto_busqueda\"] = (raw[\"nombre_proceso\"]+\". \"+raw[\"descripcion\"]).str.strip(\" .\")\nraw = raw.loc[raw.texto_busqueda.str.len()>=6].reset_index(drop=True)\nif raw.empty: raise ValueError(\"No hay documentos válidos para cargar en Atlas.\")\n# Muestra reproducible: primero ejemplos relacionados con aeronaves, luego diversidad.\nif len(raw)>MAX_FILAS:\n    semilla=raw.texto_busqueda.str.contains(\"aeronav|avion|helicopter|kfir|avi[oó]n\",case=False,regex=True,na=False)\n    prioridad=raw.loc[semilla].head(min(20,MAX_FILAS))\n    resto=raw.drop(index=prioridad.index).sample(n=MAX_FILAS-len(prioridad),random_state=9)\n    corpus=pd.concat([prioridad,resto],ignore_index=True)\nelse:\n    corpus=raw.copy()\nMODEL_NAME=\"intfloat/multilingual-e5-small\"\nLOTE = hashlib.sha256((MODEL_NAME+\"\\n\"+\"\\n\".join(corpus.id_proceso.astype(str)+\"|\"+corpus.texto_busqueda)).encode()).hexdigest()[:18]\nprint(\"ORIGEN:\",ORIGEN)\nprint(\"Total de filas válidas del origen:\",len(raw),\"· a vectorizar:\",len(corpus),\"· lote:\",LOTE)\nif len(corpus)<MAX_FILAS: print(\"Atención: el archivo solo aportó\",len(corpus),\"documentos válidos; no duplicamos filas.\")\ndisplay(corpus[[\"id_proceso\",\"nombre_proceso\",\"entidad\"]].head(5))"},{"kind":"md","source":"## Paso 2 · 12–18 min · E5 genera 384 dimensiones por documento\n\nColab ejecuta `sentence-transformers` con el modelo **`intfloat/multilingual-e5-small`**. Los documentos llevan prefijo `passage:`; la consulta utilizará `query:`. Es un modelo de embeddings, no un generador de respuestas.\n\nPor razones de tiempo, **120 documentos** son adecuados para la demostración en vivo. En un corpus de 6.000 la primera codificación puede tomar varios minutos, aunque la matriz final de 6.000 × 384 vectores float32 ocupe unos 8,8 MiB.\n\n**Comprobación visible:** debe aparecer una matriz `(N, 384)`. Los números ya están normalizados para comparar por coseno."},{"kind":"code","source":"#@title 2 · Ejecutar SentenceTransformers E5 y mostrar la matriz de embeddings\nfrom sentence_transformers import SentenceTransformer\nmodelo=SentenceTransformer(MODEL_NAME)\nmodelo.max_seq_length=256\ntextos=[\"passage: \"+str(t) for t in corpus[\"texto_busqueda\"]]\ncache=os.path.join(os.getcwd(),\"s09_atlas_\"+LOTE+\".npy\")\nstart=time.perf_counter()\nif os.path.isfile(cache):\n    embeddings=np.load(cache)\n    if embeddings.shape!=(len(corpus),384):\n        raise ValueError(\"Caché incompatible. Borra \"+cache+\" y vuelve a ejecutar.\")\n    print(\"Embeddings cargados desde caché del entorno.\")\nelse:\n    embeddings=modelo.encode(textos,normalize_embeddings=True,\n                            batch_size=32,show_progress_bar=True)\n    np.save(cache,embeddings)\nembeddings=np.asarray(embeddings,dtype=np.float32)\nassert embeddings.shape==(len(corpus),384)\nprint(\"Embeddings reales:\",embeddings.shape,\n      \"· tiempo:\",round(time.perf_counter()-start,1),\"segundos\")\nprint(\"Ejemplo de vector:\",np.round(embeddings[0,:7],3).tolist())"},{"kind":"md","source":"## Paso 3 · 18–23 min · Conectar Colab a MongoDB Atlas\n\n**Antes de ejecutar:**\n\n1. Cluster Atlas disponible y usuario de base de datos con permisos de lectura y escritura; para crear índices se requieren permisos de administración apropiados.\n2. IP de salida del entorno Colab autorizada en **Network Access**. El entorno Colab puede cambiar de IP.\n3. URI `mongodb+srv://...` copiada desde **Database → Connect → Drivers**.\n\nLa opción **`USAR_ATLAS=False`** sirve para que los estudiantes trabajen sin distribuir credenciales. Para **demostrar Atlas de verdad**, el docente cambia a `True` y escribe la URI en `getpass()`. Un `ping` correcto prueba la conexión; un error se reporta sin imprimir la URI."},{"kind":"code","source":"#@title 3 · Conectar Atlas mediante PyMongo (el docente activa True)\nfrom getpass import getpass\nfrom pymongo import MongoClient, UpdateOne\nfrom pymongo.operations import SearchIndexModel\nUSAR_ATLAS = False #@param {type:\"boolean\"}\natlas_ok=False\ncol=None\nINDEX_NAME=\"s09_vector_index\"\nNOMBRE_BD=\"clase_s09_demo\"\nNOMBRE_COL=\"secop_vectores\"\nif USAR_ATLAS:\n    try:\n        URI_ATLAS=getpass(\"Pega la URI de conexión MongoDB Atlas (oculta): \").strip()\n        if not URI_ATLAS.startswith((\"mongodb+srv://\",\"mongodb://\")):\n            raise ValueError(\"La URI de MongoDB no es válida.\")\n        client=MongoClient(URI_ATLAS,serverSelectionTimeoutMS=12000,connectTimeoutMS=12000)\n        client.admin.command(\"ping\")\n        col=client[NOMBRE_BD][NOMBRE_COL]\n        atlas_ok=True\n        print(\"ATLAS REAL · conexión confirmada por ping a:\",NOMBRE_BD+\"/\"+NOMBRE_COL)\n        del URI_ATLAS\n    except Exception as exc:\n        atlas_ok=False\n        print(\"ATLAS NO CONECTÓ:\",type(exc).__name__)\n        print(\"Revisa usuario, contraseña, IP autorizada y estado del cluster.\")\nelse:\n    print(\"RUTA LOCAL · Atlas desactivado. No habrá escritura ni consultas remotas.\")"},{"kind":"md","source":"## Paso 4 · 23–30 min · Persistir documentos y vectores en Atlas\n\nEsta es la **diferencia entre tener embeddings en NumPy y construir una base vectorial**: cada vector queda guardado como parte de un documento junto con los metadatos.\n\nUsamos `UpdateOne(..., upsert=True)` para repetir la operación sin crear copias con el mismo ID. La clave `lote` identifica los documentos del ejercicio actual, de manera que una nueva práctica no se mezcle con otra anterior.\n\n**Comprueba:** el número de documentos con ese lote en Atlas debe coincidir con las filas que enviaste. No se eliminan otras colecciones ni índices."},{"kind":"code","source":"#@title 4 · Guardar los embeddings y metadatos en la colección Atlas\natlas_cargado=False\nif atlas_ok:\n    try:\n        registros=[]\n        for i,row in corpus.reset_index(drop=True).iterrows():\n            doc={\n                \"_id\": \"s09:\"+str(row[\"id_proceso\"]),\n                \"id_proceso\":str(row[\"id_proceso\"]),\n                \"nombre_proceso\":str(row[\"nombre_proceso\"]),\n                \"descripcion\":str(row[\"descripcion\"]),\n                \"entidad\":str(row[\"entidad\"]),\n                \"url_secop\":str(row[\"url_secop\"]),\n                \"lote\":LOTE,\n                \"embedding\":embeddings[i].astype(float).tolist(),\n                \"modelo\":MODEL_NAME\n            }\n            registros.append(UpdateOne({\"_id\":doc[\"_id\"]},{\"$set\":doc},upsert=True))\n        for offset in range(0,len(registros),100):\n            col.bulk_write(registros[offset:offset+100],ordered=False)\n        guardados=col.count_documents({\"lote\":LOTE})\n        atlas_cargado=(guardados==len(corpus))\n        print(\"ATLAS REAL · documentos del lote:\",guardados,\n              \"de\",len(corpus),\"· inserción verificable:\",atlas_cargado)\n        if not atlas_cargado:\n            print(\"Advertencia: revisa que el lote se haya cargado completamente.\")\n    except Exception as exc:\n        print(\"Error al insertar en Atlas:\",type(exc).__name__)\nelse:\n    print(\"Atlas desactivado: no se insertó ningún documento remoto.\")"},{"kind":"md","source":"## Paso 5 · 30–40 min · Crear índice y esperar `queryable=True`\n\nUn índice **MongoDB Vector Search** conecta el campo `embedding` (384 dimensiones, coseno) con la búsqueda. Para filtrar necesitamos declarar campos de tipo `filter`, aquí `lote` y `entidad`.\n\n`create_search_index()` inicia un proceso asíncrono: **la instrucción puede terminar antes de que el índice esté listo**. Por eso inspeccionamos `list_search_indexes()` y esperamos como máximo 75 segundos en esta clase.\n\n**Límite para la demostración:** evita crear 30 índices diferentes en un mismo cluster gratuito. El docente puede preparar un índice antes de clase."},{"kind":"code","source":"#@title 5 · Crear o reutilizar el índice MongoDB Vector Search\nindice_creado=False\ndefinition={\"fields\":[\n    {\"type\":\"vector\",\"path\":\"embedding\",\"numDimensions\":384,\"similarity\":\"cosine\"},\n    {\"type\":\"filter\",\"path\":\"lote\"},\n    {\"type\":\"filter\",\"path\":\"entidad\"}\n]}\nif atlas_ok and atlas_cargado:\n    try:\n        existentes={ix.get(\"name\"):ix for ix in col.list_search_indexes()}\n        if INDEX_NAME in existentes:\n            actual=existentes[INDEX_NAME].get(\"latestDefinition\") or existentes[INDEX_NAME].get(\"definition\") or {}\n            if actual and actual!=definition:\n                print(\"AVISO: índice existente con configuración distinta; revisa antes de actualizarlo.\")\n                indice_creado=False\n            else:\n                indice_creado=True\n                print(\"ATLAS · índice ya existe:\",INDEX_NAME)\n        else:\n            modelo_indice=SearchIndexModel(\n                definition=definition,name=INDEX_NAME,type=\"vectorSearch\")\n            col.create_search_index(model=modelo_indice)\n            indice_creado=True\n            print(\"ATLAS · creación del índice solicitada:\",INDEX_NAME)\n    except Exception as exc:\n        print(\"No fue posible crear/verificar índice:\",type(exc).__name__)\nelse:\n    print(\"Índice no solicitado: Atlas no está listo o el lote no se cargó.\")"},{"kind":"code","source":"#@title 6 · Verificar estado real del índice (máximo 75 segundos)\nindice_queryable=False\nif atlas_ok and indice_creado:\n    for intento in range(15):\n        try:\n            datos=list(col.list_search_indexes(INDEX_NAME))\n            indice_queryable=bool(datos and datos[0].get(\"queryable\") is True)\n            print(\"Índice:\",INDEX_NAME,\n                  \"· disponible:\",indice_queryable,\n                  \"· revisión:\",intento+1)\n            if indice_queryable:break\n            if intento<14:time.sleep(5)\n        except Exception as exc:\n            print(\"No se pudo consultar el estado:\",type(exc).__name__)\n            break\n    if not indice_queryable:\n        print(\"El índice aún no está queryable. Espera y reejecuta esta celda.\")\nelse:\n    print(\"SIN ÍNDICE ATLAS verificado. La consulta remota no se ejecutará.\")"},{"kind":"md","source":"## Paso 6 · 40–48 min · Ejecutar `$vectorSearch` con el índice real\n\nLa **consulta también se vectoriza con E5**. Atlas recibe ese vector en `queryVector`, busca en el campo `embedding` y devuelve un **Top-k**.\n\nEl campo `lote` limita la búsqueda a los documentos cargados; `entidad` puede agregarse como filtro. El pipeline corre remotamente con `col.aggregate([...])`. Si el índice no está disponible, la celda usa NumPy y lo declara como **LOCAL**, nunca como Atlas.\n\n**Esta es la prueba principal de la sesión.** Cambia el texto de consulta y muestra cómo varían los resultados."},{"kind":"code","source":"#@title 7 · Ejecutar búsqueda Atlas real y compararla con referencia NumPy\nCONSULTA = \"reparación de aviones militares\" #@param {type:\"string\"}\nTOP_K = 5 #@param [3,5,10] {type:\"raw\"}\nNUM_CANDIDATES = 100 #@param [50,100,200] {type:\"raw\"}\nFILTRO_ENTIDAD = \"\" #@param {type:\"string\"}\nTOP_K=int(TOP_K)\nNUM_CANDIDATES=max(int(NUM_CANDIDATES),20*TOP_K)\nif not CONSULTA.strip():raise ValueError(\"Escribe una consulta antes de buscar.\")\nq=modelo.encode([\"query: \"+CONSULTA.strip()],normalize_embeddings=True)[0]\nfiltro={\"lote\":LOTE}\nif FILTRO_ENTIDAD.strip():filtro[\"entidad\"]=FILTRO_ENTIDAD.strip()\n# Referencia exacta en NumPy: NUNCA se presenta como ejecutada en Atlas.\ncandidatos=np.flatnonzero(\n    corpus[\"entidad\"].astype(str).eq(FILTRO_ENTIDAD).to_numpy()\n) if FILTRO_ENTIDAD else np.arange(len(corpus))\npuntuaciones=embeddings[candidatos] @ q if len(candidatos) else np.array([])\norden=candidatos[np.argsort(-puntuaciones)[:TOP_K]] if len(candidatos) else np.array([],dtype=int)\nresultados_numpy=corpus.iloc[orden][\n    [\"id_proceso\",\"nombre_proceso\",\"entidad\",\"url_secop\"]].copy()\nresultados_numpy[\"score_coseno\"]=np.asarray(embeddings[orden] @ q,dtype=float)\nresultados_numpy=resultados_numpy.reset_index(drop=True)\nprint(\"NUMPY LOCAL · Top-k exacto sobre los vectores en memoria:\")\ndisplay(resultados_numpy)\nresultados_atlas=pd.DataFrame()\nlatencia_atlas_ms=None\npipeline_vector=None\nif atlas_ok and atlas_cargado and indice_queryable:\n    etapa={\"$vectorSearch\":{\n        \"index\":INDEX_NAME,\"path\":\"embedding\",\n        \"queryVector\":q.astype(float).tolist(),\n        \"numCandidates\":NUM_CANDIDATES,\"limit\":TOP_K,\n        \"filter\":filtro\n    }}\n    pipeline_vector=[etapa,{\"$project\":{\n        \"_id\":1,\"id_proceso\":1,\"nombre_proceso\":1,\"entidad\":1,\"url_secop\":1,\n        \"score\":{\"$meta\":\"vectorSearchScore\"}}}]\n    try:\n        tic=time.perf_counter()\n        resultados_atlas=pd.DataFrame(list(col.aggregate(pipeline_vector,maxTimeMS=30000)))\n        latencia_atlas_ms=round((time.perf_counter()-tic)*1000,1)\n        print(\"MONGODB ATLAS REAL · $vectorSearch:\",len(resultados_atlas),\n              \"resultados · latencia total:\",latencia_atlas_ms,\"ms\")\n        display(resultados_atlas)\n    except Exception as exc:\n        print(\"ATLAS NO RESPONDIÓ A $vectorSearch:\",type(exc).__name__)\n        print(\"La tabla anterior corresponde exclusivamente a NumPy LOCAL.\")\nelse:\n    print(\"NO SE EJECUTÓ ATLAS. Se muestran solo resultados NumPy LOCAL.\")"},{"kind":"code","source":"#@title 8 · Medir coincidencia de vecinos y descargar evidencia (sin credenciales)\nfrom datetime import datetime, timezone\natlas_real=(not resultados_atlas.empty and pipeline_vector is not None)\nids_local=set(resultados_numpy[\"id_proceso\"].astype(str))\nids_atlas=set(resultados_atlas[\"id_proceso\"].astype(str)) if atlas_real else set()\ncoincidencia_at_k=round(len(ids_local & ids_atlas)/len(ids_local),3) if ids_local and atlas_real else None\nprint(\"Motor remoto ejecutado:\", \"MongoDB Atlas Vector Search\" if atlas_real else \"NO · respaldo NumPy\")\nif atlas_real:\n    print(\"Coincidencia con vecinos exactos locales:\",coincidencia_at_k,\n          \"· latencia remota cliente-servidor:\",latencia_atlas_ms,\"ms\")\nelse:\n    print(\"Sin comparación Atlas/NumPy. No se atribuyen resultados locales a Atlas.\")\nevidencia={\n  \"sesion\":9,\"tipo\":\"atlas_vector_search_demo\",\"momento_utc\":datetime.now(timezone.utc).isoformat(),\n  \"motor_ejecutado\":\"MongoDB Atlas Vector Search\" if atlas_real else \"NumPy local (respaldo)\",\n  \"origen\":ORIGEN,\"lote\":LOTE,\"documentos\":len(corpus),\n  \"modelo\":MODEL_NAME,\"dimensiones\":384,\n  \"database\":NOMBRE_BD if atlas_real else None,\n  \"collection\":NOMBRE_COL if atlas_real else None,\n  \"index\":INDEX_NAME if atlas_real else None,\n  \"queryable\":bool(indice_queryable),\"consulta\":CONSULTA,\"top_k\":TOP_K,\n  \"numCandidates\":NUM_CANDIDATES if atlas_real else None,\n  \"filtro\":filtro,\"latencia_atlas_ms\":latencia_atlas_ms,\n  \"coincidencia_at_k_vs_numpy\":coincidencia_at_k,\n  \"resultados_atlas\":resultados_atlas.to_dict(\"records\") if atlas_real else [],\n  \"resultados_locales\":resultados_numpy.to_dict(\"records\"),\n  \"nota\":\"Coincidencia de vecinos no mide relevancia humana. No guarda URI ni contraseña.\"\n}\nruta_salida=\"s09_atlas_evidencia.json\"\nwith open(ruta_salida,\"w\",encoding=\"utf-8\") as f:\n    json.dump(evidencia,f,ensure_ascii=False,indent=2,\n              default=lambda v:v.item() if hasattr(v,\"item\") else str(v))\nprint(\"JSON:\",ruta_salida,\"· motor:\",evidencia[\"motor_ejecutado\"])\ntry:\n    from google.colab import files\n    files.download(ruta_salida)\nexcept ImportError:\n    print(\"Fuera de Colab, abre el JSON en el directorio de trabajo.\")"},{"kind":"md","source":"## Fin del tramo de 55 minutos — la sesión operativa termina aquí\n\n**Evidencia principal:** colección cargada, índice consultable, etapa real `$vectorSearch`, resultados y JSON sin secretos. Si Atlas no conectó, explica el fallo y diferencia la ruta local.\n\n**Para después de clase:** si deseas comparar HNSW/ANN con exacta, ampliar a 6.000 documentos, experimentar con ortografía, RRF o cambiar a un CSV propio, usa el **apéndice siguiente**. No es necesario para demostrar la operación central de Atlas en una hora.\n\n---\n\n## APÉNDICE · Recuperación BM25, ortografía, RRF y transferencia a otros corpus\n\nLas celdas que siguen son el laboratorio extenso original. **No forman parte de la ruta exprés** y pueden cambiar variables como `corpus`, `embeddings` y `modelo`. Ejecútalas en otra sesión o en una copia limpia si quieres continuar sin alterar la demostración Atlas."},{"kind":"md","source":"## Del índice invertido al espacio vectorial\n\nEn S07 aprendiste recuperación lexical con tokens, índice invertido y BM25. S09 agrega otra representación.\n\n| Consulta | Documento potencialmente relevante |\n|---|---|\n| reparar aviones militares | mantenimiento programado de aeronaves KFIR |\n| conectividad durante una emergencia | servicios TIC en emergencia sanitaria |\n| infraestructura para entrenamiento deportivo | centro de alto rendimiento deportivo |\n\n**PARA LLEVAR.** La búsqueda semántica no reemplaza BM25. Recupera por cercanía bajo una representación aprendida."},{"kind":"md","source":"## Vocabulario mínimo\n\n| Término | Significa aquí | No significa |\n|---|---|---|\n| embedding | vector numérico de un texto | explicación del texto |\n| dimensión | número de componentes | número de palabras |\n| coseno | cercanía angular | probabilidad |\n| Top-k | k vecinos recuperados | k respuestas verdaderas |\n| metadata | entidad, modalidad, ID, URL | parte obligatoria del vector |\n| vector index | estructura de recuperación | modelo de embeddings |\n| ANN | vecinos aproximados | búsqueda aleatoria |\n| ENN/exacta | búsqueda exacta bajo el motor | garantía de relevancia humana |"},{"kind":"code","source":"import numpy as np\n\nconsulta = np.array([0.90, 0.85])\ndoc_a = np.array([0.88, 0.92])\ndoc_b = np.array([0.95, 0.10])\n\ndef coseno(a, b):\n    a, b = np.asarray(a, dtype=float), np.asarray(b, dtype=float)\n    den = np.linalg.norm(a) * np.linalg.norm(b)\n    if not den:\n        raise ValueError(\"El coseno requiere vectores no nulos.\")\n    return float(np.dot(a, b) / den)\n\nprint(\"Consulta frente a mantenimiento de aeronaves:\", round(coseno(consulta, doc_a), 4))\nprint(\"Consulta frente a mantenimiento de edificio:\", round(coseno(consulta, doc_b), 4))\nprint(\"Interpretación: la cercanía no equivale a probabilidad ni a juicio de relevancia.\")"},{"kind":"md","source":"**Cómo se lee.** Mayor coseno = orientación más parecida bajo esta representación.\n\n**Qué nos dice.** El documento A queda más cerca de la necesidad.\n\n**Qué NO permite concluir todavía.** Falta un juicio humano de relevancia.\n\n**Error común.** Leer 0.91 como “91 % de probabilidad”. No es una probabilidad."},{"kind":"md","source":"## ETAPA 1 · Elegir la fuente y preparar datos propios\n\n**¿Qué se necesita?** Un CSV con, como mínimo, un identificador único y una columna textual. Lo ideal es tener título, descripción, grupo y enlace de consulta.\n\n**¿De dónde sale?** SECOP del repositorio del curso, un CSV público descargable o un archivo que exportaste de otro sistema. Para ejecutar el ejemplo no hace falta usuario LMS.\n\n| Contexto | Identificador | Título | Texto | Grupo | URL |\n| --- | --- | --- | --- | --- | --- |\n| Contratación SECOP | id_proceso | nombre_proceso | descripcion | entidad | url_secop |\n| Atención ciudadana | radicado | asunto | contenido | dependencia | enlace |\n| Jurisprudencia | expediente | título | extracto | tribunal | url |\n| Tickets de soporte | ticket_id | asunto | detalle | equipo | enlace |\n\nEn **otro contexto**, cambia la fuente en la primera celda y el mapeo en la siguiente. No necesitas volver a inventar BM25/E5/RRF. Un modelo especializado puede ser necesario si tu evaluación demuestra que E5 falla en ese dominio.\n\n**Privacidad:** no subas a Colab datos personales, reservados o protegidos sin autorización. Usa un extracto anonimizado para aprender.\n\n**Prueba de calidad:** antes de entrenar nada, cuenta documentos, IDs únicos, textos vacíos y la proporción de filas que sobrevivieron al filtrado.\n\n**Respaldo:** si el CSV remoto no está disponible, elige *Ejemplo sintético de respaldo*; son seis registros explícitamente ficticios y no se presentarán como datos SECOP. Para CSV separados por punto y coma puedes cambiar **DELIMITADOR**.\n\n**Corpus recomendado:** 6.000 documentos. El modo «SECOP ampliado (6000)» conserva los registros válidos del CSV del curso y, si faltan, incorpora procesos reales de la [API pública SECOP II](https://www.datos.gov.co/Gastos-Gubernamentales/SECOP-II-Procesos-de-Contrataci-n/p6dx-8zbt). La consola informará las filas efectivamente recuperadas, su procedencia y los posibles fallos de red. No se replican registros."},{"kind":"code","source":"#@title 1. Selecciona de dónde salen tus datos (SECOP, URL o CSV propio)\nimport io, os, hashlib, json, re, time\nimport pandas as pd, numpy as np\nfrom IPython.display import display\nMODE_DATOS = \"SECOP ampliado (6000)\" #@param [\"SECOP ampliado (6000)\",\"SECOP del curso\",\"SECOP II oficial (API)\",\"CSV desde URL\",\"Subir CSV desde computador\",\"Ejemplo sintético de respaldo\"]\nURL_CSV = \"\" #@param {type:\"string\"}\nARCHIVO_CSV = \"\" #@param {type:\"string\"}\nLIMITE = 6000 #@param {type:\"integer\"}\nif not 1 <= LIMITE <= 10000:\n    raise ValueError(\"El límite del taller debe estar entre 1 y 10.000 documentos.\")\nDELIMITADOR = \"coma\" #@param [\"coma\",\"punto y coma\",\"tabulador\",\"autodetectar\"]\nCODIFICACION = \"utf-8\" #@param [\"utf-8\",\"latin-1\",\"utf-8-sig\"]\nURL_SECOP = \"https://raw.githubusercontent.com/jazaineam1/BigData2026/main/Datos/s06_contexto_relacional.csv\"\nif MODE_DATOS == \"Ejemplo sintético de respaldo\":\n    FUENTE_CSV = \"ejemplo_didactico_sintetico\"\nelif MODE_DATOS in (\"SECOP del curso\",\"SECOP ampliado (6000)\"):\n    FUENTE_CSV = URL_SECOP\nelif MODE_DATOS == \"SECOP II oficial (API)\":\n    FUENTE_CSV = \"https://www.datos.gov.co/resource/p6dx-8zbt.json\"\nelif MODE_DATOS == \"CSV desde URL\":\n    if not URL_CSV.startswith((\"https://\",\"http://\")):\n        raise ValueError(\"Copia la URL directa de un archivo CSV público, no una página HTML.\")\n    FUENTE_CSV = URL_CSV.strip()\nelse:\n    if ARCHIVO_CSV and os.path.isfile(ARCHIVO_CSV):\n        FUENTE_CSV = ARCHIVO_CSV\n    else:\n        try:\n            from google.colab import files\n            subida = files.upload()\n            if not subida:\n                raise ValueError(\"No se seleccionó ningún archivo CSV.\")\n            FUENTE_CSV = next(iter(subida))\n        except ImportError:\n            raise RuntimeError(\"Indica ARCHIVO_CSV con una ruta existente o usa Google Colab para subir el archivo.\")\ntry:\n    if MODE_DATOS == \"Ejemplo sintético de respaldo\":\n        datos_originales=pd.DataFrame([\n          {\"id_proceso\":\"DEMO-1\",\"nombre_proceso\":\"Mantenimiento programado de aeronaves KFIR\",\"descripcion\":\"Inspección preventiva y repuestos de aviones militares\",\"entidad\":\"Aeronáutica\",\"url_secop\":\"\"},\n          {\"id_proceso\":\"DEMO-2\",\"nombre_proceso\":\"Compra de licencias de software\",\"descripcion\":\"Adquisición de plataformas informáticas\",\"entidad\":\"Tecnología\",\"url_secop\":\"\"},\n          {\"id_proceso\":\"DEMO-3\",\"nombre_proceso\":\"Inspección de aeronaves C-130\",\"descripcion\":\"Reparación y pruebas técnicas de aviones\",\"entidad\":\"Aeronáutica\",\"url_secop\":\"\"},\n          {\"id_proceso\":\"DEMO-4\",\"nombre_proceso\":\"Conectividad en emergencia sanitaria\",\"descripcion\":\"Servicio de internet para atención de salud\",\"entidad\":\"Salud\",\"url_secop\":\"\"},\n          {\"id_proceso\":\"DEMO-5\",\"nombre_proceso\":\"Construcción de centro deportivo\",\"descripcion\":\"Obra para entrenamiento de alto rendimiento\",\"entidad\":\"Deporte\",\"url_secop\":\"\"},\n          {\"id_proceso\":\"DEMO-6\",\"nombre_proceso\":\"Seguridad en edificios militares\",\"descripcion\":\"Vigilancia y monitoreo de instalaciones\",\"entidad\":\"Seguridad\",\"url_secop\":\"\"}\n        ])\n        print(\"AVISO: datos sintéticos únicamente para practicar la técnica; no representan SECOP real.\")\n    elif MODE_DATOS == \"SECOP II oficial (API)\":\n        import requests\n        res=requests.get(FUENTE_CSV,params={\n            \"$select\":\"id_del_proceso,nombre_del_procedimiento,descripci_n_del_procedimiento,entidad\",\n            \"$where\":\"id_del_proceso is not null and nombre_del_procedimiento is not null\",\n            \"$limit\":min(10000,LIMITE*2)},timeout=40)\n        res.raise_for_status()\n        datos_originales=pd.DataFrame(res.json()).rename(columns={\n            \"id_del_proceso\":\"id_proceso\",\"nombre_del_procedimiento\":\"nombre_proceso\",\n            \"descripci_n_del_procedimiento\":\"descripcion\"})\n        datos_originales[\"url_secop\"]=\"\"\n    else:\n        sep={\"coma\":\",\",\"punto y coma\":\";\",\"tabulador\":\"\\t\",\"autodetectar\":None}[DELIMITADOR]\n        parametros={\"dtype\":str,\"keep_default_na\":False,\"encoding\":CODIFICACION}\n        if sep is None:parametros.update(sep=None,engine=\"python\")\n        else:parametros[\"sep\"]=sep\n        datos_originales=pd.read_csv(FUENTE_CSV,**parametros)\nexcept Exception as exc:\n    raise RuntimeError(\"No fue posible leer el CSV. Comprueba el enlace o el delimitador/encoding.\") from exc\nif datos_originales.empty:\n    raise ValueError(\"El CSV está vacío.\")\nFUENTE_DESCRIPCION = {\"modo\":MODE_DATOS,\"origen\":FUENTE_CSV,\"filas_fuente\":len(datos_originales),\n \"fuente_ampliacion\":None,\"filas_ampliacion\":0}\nprint(\"Meta:\",LIMITE,\"registros como máximo. No se duplicarán datos para completar el número.\")\nprint(\"Origen:\",FUENTE_CSV)\nprint(\"Filas:\",len(datos_originales),\"· columnas:\",list(datos_originales.columns))\ndisplay(datos_originales.head(4))"},{"kind":"md","source":"### Mapeo operativo: tu CSV → esquema del buscador\n\nLas funciones que siguen esperan cinco columnas estándar. **Tú defines de qué columna original viene cada una.**\n\nSeñala una columna ID válida; el título y el cuerpo textual deben existir al menos uno de los dos. Grupo y URL son opcionales. El programa muestra una vista previa antes de calcular embeddings para que puedas detectar mapeos incorrectos.\n\n**Ejemplo PQRS:** sustituye ID por radicado, título por asunto, texto por contenido, grupo por dependencia y URL por enlace. Los pasos 3–9 ya no cambian."},{"kind":"code","source":"#@title 2. Identifica y configura las columnas de tu propio contexto\n# Si cambias el CSV, adapta estas cinco columnas. El ID y un campo textual son obligatorios.\n# SECOP: id_proceso, nombre_proceso, descripcion, entidad, url_secop\n# PQRS: radicado, asunto, contenido, dependencia, url\n# Jurisprudencia: expediente, titulo, resumen, tribunal, enlace\nCOLUMNA_ID = \"id_proceso\" #@param {type:\"string\"}\nCOLUMNA_TITULO = \"nombre_proceso\" #@param {type:\"string\"}\nCOLUMNA_TEXTO = \"descripcion\" #@param {type:\"string\"}\nCOLUMNA_GRUPO = \"entidad\" #@param {type:\"string\"}\nCOLUMNA_ENLACE = \"url_secop\" #@param {type:\"string\"}\n# Opcionales vacíos: el sistema los rellena sin inventar datos.\nmapa={\"id_proceso\":COLUMNA_ID.strip(),\"nombre_proceso\":COLUMNA_TITULO.strip(),\n      \"descripcion\":COLUMNA_TEXTO.strip(),\"entidad\":COLUMNA_GRUPO.strip(),\n      \"url_secop\":COLUMNA_ENLACE.strip()}\nnecesarias=[mapa[\"id_proceso\"],mapa[\"nombre_proceso\"],mapa[\"descripcion\"]]\nif not mapa[\"id_proceso\"] or mapa[\"id_proceso\"] not in datos_originales.columns:\n    raise ValueError(\"Especifica una columna ID existente y única (ej. radicado o expediente).\")\nif not any(k and k in datos_originales.columns for k in necesarias[1:]):\n    raise ValueError(\"Debes indicar un título o texto válido para construir el buscador.\")\nestandar=pd.DataFrame(index=datos_originales.index)\nfor destino,origen in mapa.items():\n    estandar[destino]=datos_originales[origen].astype(str) if origen in datos_originales.columns else \"\"\nestandar[\"modalidad\"] = \"\"  # compatibilidad con el ejemplo opcional de Atlas\nestandar[\"fuente_registro\"] = (\"SECOP II oficial, API\" if MODE_DATOS == \"SECOP II oficial (API)\"\n                            else \"CSV externo\" if MODE_DATOS not in (\"SECOP del curso\",\"SECOP ampliado (6000)\")\n                            else \"Archivo SECOP del curso\")\nestandar[\"id_proceso\"]=estandar[\"id_proceso\"].str.strip()\nestandar=estandar.loc[estandar[\"id_proceso\"].ne(\"\")].drop_duplicates(\"id_proceso\").copy()\nestandar[\"nombre_proceso\"]=estandar[\"nombre_proceso\"].str.strip()\nestandar[\"descripcion\"]=estandar[\"descripcion\"].str.strip()\nestandar[\"texto_busqueda\"]=(estandar[\"nombre_proceso\"]+\". \"+estandar[\"descripcion\"]).str.strip(\" .\")\nestandar=estandar.loc[estandar[\"texto_busqueda\"].str.len().ge(6)].reset_index(drop=True)\nif estandar.empty:\n    raise ValueError(\"No hay registros con ID y texto útiles. Revisa el mapeo.\")\n# Cuando el CSV del curso no alcanza la meta, completar con procesos reales de la API oficial.\nif MODE_DATOS == \"SECOP ampliado (6000)\" and len(estandar)<LIMITE:\n    try:\n        import requests\n        api_url=\"https://www.datos.gov.co/resource/p6dx-8zbt.json\"\n        falta=LIMITE-len(estandar)\n        respuesta=requests.get(api_url,params={\n          \"$select\":\"id_del_proceso,nombre_del_procedimiento,descripci_n_del_procedimiento,entidad\",\n          \"$where\":\"id_del_proceso is not null and nombre_del_procedimiento is not null\",\n          \"$limit\":min(10000,max(falta*2,6500))},timeout=40)\n        respuesta.raise_for_status()\n        ext=pd.DataFrame(respuesta.json())\n        traduccion={\"id_del_proceso\":\"id_proceso\",\"nombre_del_procedimiento\":\"nombre_proceso\",\n           \"descripci_n_del_procedimiento\":\"descripcion\",\"entidad\":\"entidad\"}\n        if not set(traduccion).issubset(ext.columns):\n            raise ValueError(\"La API oficial no entregó las columnas esperadas.\")\n        ext=ext.rename(columns=traduccion)\n        for col in [\"id_proceso\",\"nombre_proceso\",\"descripcion\",\"entidad\"]:\n            ext[col]=ext[col].fillna(\"\").astype(str)\n        ext[\"url_secop\"]=\"\"\n        ext[\"modalidad\"]=\"\"\n        ext[\"fuente_registro\"]=\"SECOP II oficial, API\"\n        ext[\"texto_busqueda\"]=(ext[\"nombre_proceso\"]+\". \"+ext[\"descripcion\"]).str.strip(\" .\")\n        ext=ext.loc[ext[\"id_proceso\"].str.strip().ne(\"\") & ext[\"texto_busqueda\"].str.len().ge(6)]\n        ext=ext.loc[~ext[\"id_proceso\"].isin(estandar[\"id_proceso\"])]\n        ext=ext.drop_duplicates(\"id_proceso\").head(falta)\n        if not ext.empty:\n            estandar=pd.concat([estandar,ext[estandar.columns]],ignore_index=True)\n        FUENTE_DESCRIPCION[\"fuente_ampliacion\"]=api_url\n        FUENTE_DESCRIPCION[\"filas_ampliacion\"]=len(ext)\n        print(\"Procesos adicionales de SECOP II oficial:\",len(ext))\n    except Exception as ex:\n        print(\"AVISO: no se pudo ampliar SECOP por API oficial:\",type(ex).__name__,str(ex)[:150])\n        print(\"Continuamos únicamente con procesos disponibles en el CSV del curso.\")\nif LIMITE>0 and len(estandar)>LIMITE:\n    # Mantener ejemplos de la clase cuando son datos SECOP; mezclar con muestra reproducible.\n    if MODE_DATOS in (\"SECOP del curso\",\"SECOP ampliado (6000)\"):\n        referencia=estandar[\"texto_busqueda\"].str.lower()\n        anclas=estandar.loc[referencia.str.contains(r\"kfir|aeronav|helic[oó]pter|avi[oó]n|conectividad|emergencia|deportiv|entrenamiento\",regex=True)].head(min(150,LIMITE))\n        extra=estandar.drop(index=anclas.index).sample(n=min(LIMITE-len(anclas),len(estandar)-len(anclas)),random_state=9)\n        estandar=pd.concat([anclas,extra],ignore_index=True)\n    else:\n        estandar=estandar.sample(n=LIMITE,random_state=9).reset_index(drop=True)\ncorpus=estandar.reset_index(drop=True)\nMAPEO_COLUMNAS=dict(mapa)\nCORPUS_HUELLA=hashlib.sha256((\"\\n\".join(corpus[\"id_proceso\"]+\"|\"+corpus[\"texto_busqueda\"])).encode(\"utf-8\")).hexdigest()\nprint(\"Documentos listos:\",len(corpus),\"· meta solicitada:\",LIMITE,\"· origen CSV:\",len(datos_originales))\nprint(\"Registros por fuente:\",corpus[\"fuente_registro\"].value_counts().to_dict())\nif len(corpus)<LIMITE:\n    print(\"AVISO: se indexarán\",len(corpus),\"registros reales y únicos; no se inventarán documentos.\")\nprint(\"Identidad única:\",corpus[\"id_proceso\"].nunique()==len(corpus))\nprint(\"Campos estándar:\",list(corpus.columns))\ndisplay(corpus[[\"id_proceso\",\"nombre_proceso\",\"descripcion\",\"entidad\",\"url_secop\"]].head(5))"},{"kind":"md","source":"## ETAPA 2 · Construir el motor lexical\n\n**Qué ocurre:** las descripciones pasan por un analizador de tokens; BM25 pondera términos según su frecuencia y rareza. No es una búsqueda semántica.\n\n**Qué debes verificar:** si buscas un código exacto y el corpus lo contiene, las coincidencias lexicales pueden ser especialmente útiles. Prueba una expresión reformulada para descubrir sus límites.\n\n**De dónde sale:** el paquete Python [rank-bm25](https://pypi.org/project/rank-bm25/). El analizador aquí es simple y no reemplaza la configuración de Elasticsearch vista en S07.\n\n### ¿Qué ocurre con la ortografía?\n\n**BM25 puro** no es un corrector: si escribes `aeronavess`, no coincide con `aeronaves`. Esta versión normaliza mayúsculas y acentos para la parte lexical (`reparación` y `reparacion` comparten token) y propone **correcciones difusas** con [RapidFuzz](https://github.com/rapidfuzz/RapidFuzz), comparando la palabra con el vocabulario obtenido del corpus.\n\n**¿Qué modelo corrige?** Ningún modelo generativo: RapidFuzz mide similitud de cadenas mediante distancia de edición. Solo propone cambios con umbrales conservadores, y no toca códigos numéricos/IDs. Las sugerencias pueden equivocarse: hay que confirmarlas.\n\n**E5 semántico** usa un encoder multilingüe de 384 dimensiones; puede ser tolerante a algunas faltas, pero **no es un sistema de autocorrección**. RRF fusiona rankings y no corrige errores. En la consola puedes comparar **Sin corrección**, **Sugerir (sin aplicar)** y **Aplicar sugerencias (explícito)**."},{"kind":"code","source":"#@title 3. Construye el índice lexical y tu primera búsqueda BM25\nimport re, unicodedata\nfrom collections import Counter\nfrom functools import lru_cache\nfrom rank_bm25 import BM25Okapi\nfrom rapidfuzz import process, fuzz\nfrom rapidfuzz.distance import Levenshtein\ndef normalizar(texto):\n    # Solo para buscar palabras (BM25), sin alterar el texto original de E5.\n    texto=unicodedata.normalize(\"NFKD\",str(texto).lower())\n    return \"\".join(x for x in texto if not unicodedata.combining(x))\n\ndef tokens(texto):\n    return re.findall(r\"[a-z0-9]+\",normalizar(texto))\ndocumentos_tokenizados=[tokens(t) for t in corpus[\"texto_busqueda\"]]\nindice_lexical=BM25Okapi(documentos_tokenizados)\nfrecuencias=Counter(t for doc in documentos_tokenizados for t in set(doc))\nvocabulario=set(frecuencias)\ncandidatos_ortograficos=sorted(t for t,c in frecuencias.items()\n                                if len(t)>=5 and c>=2 and not any(x.isdigit() for x in t))\n@lru_cache(maxsize=512)\ndef sugerir_termino(palabra):\n    # Diccionario extraído del corpus: NO es un LLM ni un corrector universal.\n    if palabra in vocabulario or len(palabra)<5 or any(x.isdigit() for x in palabra):\n        return palabra\n    vecino=process.extractOne(palabra,candidatos_ortograficos,scorer=fuzz.ratio,score_cutoff=78)\n    if not vecino:return palabra\n    propuesta=vecino[0]\n    max_errores=1 if len(palabra)<=6 else 2\n    return propuesta if Levenshtein.distance(palabra,propuesta)<=max_errores else palabra\n\ndef sugerir_correcciones(consulta):\n    # Conserva el texto original. El usuario decide si aplica sugerencias.\n    sugerencias={t:sugerir_termino(t) for t in tokens(consulta)}\n    cambios={t:alt for t,alt in sugerencias.items() if t!=alt}\n    corregida=\" \".join(sugerencias[t] for t in tokens(consulta))\n    return corregida,cambios\nprint(\"Vocabulario para sugerencias:\",len(candidatos_ortograficos),\"términos; no modifica las consultas sin permiso.\")\ndef buscar_lexical(consulta,k=5,entidad=None):\n    q=tokens(consulta)\n    columnas=[\"id_proceso\",\"nombre_proceso\",\"descripcion\",\"entidad\",\"url_secop\",\"score_lexical\"]\n    if not q: return pd.DataFrame(columns=columnas)\n    scores=np.asarray(indice_lexical.get_scores(q),dtype=float)\n    candidatos=np.arange(len(corpus))\n    if entidad: candidatos=candidatos[corpus[\"entidad\"].eq(entidad).to_numpy()]\n    # BM25 puede producir scores no positivos en textos con palabras excesivamente frecuentes.\n    # No inventar coincidencias: exigir al menos un token compartido.\n    matched=np.array([bool(set(q).intersection(documentos_tokenizados[i])) for i in candidatos])\n    candidatos=candidatos[matched]\n    orden=candidatos[np.argsort(-scores[candidatos],kind=\"stable\")[:max(0,int(k))]]\n    data=corpus.iloc[orden][columnas[:-1]].copy()\n    data[\"score_lexical\"]=scores[orden]\n    return data.reset_index(drop=True)\nconsulta_prueba=\"reparación de aviones militares\" if MODE_DATOS==\"SECOP del curso\" else str(corpus.iloc[0][\"nombre_proceso\"])\nprint(\"Consulta de ejemplo:\",consulta_prueba)\ndisplay(buscar_lexical(consulta_prueba,3)[[\"nombre_proceso\",\"score_lexical\"]])\nprint(\"BM25 construye puntuaciones a partir de tokens; no entiende significado por sí solo.\")"},{"kind":"code","source":"#@title Prueba de ortografía: término exacto frente a error tipográfico (BM25)\nconsulta_correcta=\"mantenimiento de aeronaves\"\nconsulta_con_error=\"mantenimieto de aeronavess\"\ncorregida,cambios=sugerir_correcciones(consulta_con_error)\nprint(\"Consulta correcta:\",consulta_correcta)\nprint(\"Consulta mal escrita:\",consulta_con_error)\nprint(\"Sugerencias basadas en el corpus:\",cambios if cambios else \"ninguna segura\")\nprint(\"Texto propuesto:\",corregida)\nfor nombre,q in [(\"BM25 correcto\",consulta_correcta),(\"BM25 error\",consulta_con_error),\n                 (\"BM25 con sugerencia\",corregida)]:\n    tabla=buscar_lexical(q,5)\n    print(nombre,\":\",len(tabla),\"resultados · IDs Top5:\",tabla[\"id_proceso\"].astype(str).tolist())\nprint(\"Observa qué cambia: una corrección puede ayudar o perjudicar; compara relevancia humana.\")\n\n**Práctica:** escribe `mantenimieto de aeronavess`; compara el modo exacto, la sugerencia y la corrección explícita. No consideres el cambio automáticamente mejor: verifica la pertinencia de los documentos recuperados.\nprint(\"Nota: los errores tipográficos se comprueban también con E5 en la consola tras indexar los documentos.\")"},{"kind":"md","source":"### ¿Qué modelos se están usando? ¿Corrigen errores ortográficos?\n\n| Etapa | Herramienta / modelo | Comportamiento ante errores |\n|---|---|---|\n| Coincidencia lexical | `rank-bm25` · `BM25Okapi` | No corrige faltas; sí normalizamos acentos y mayúsculas |\n| Sugerencias ortográficas | `RapidFuzz`, vocabulario del corpus y distancia de edición | Propone cambios plausibles, nunca silenciosos |\n| Semántica | `intfloat/multilingual-e5-small` · encoder multilingüe de 384 dimensiones | Tolera algunas variantes, pero **no es un corrector** |\n| Fusión | Reciprocal Rank Fusion · constante 60 | Combina posiciones, no corrige nada |\n| Evaluación | Relevancia humana + Precision@k | Comprueba pertinencia, no se deduce del score |\n\nE5 es un **modelo preentrenado de embeddings**, no un LLM generativo. Emplea `passage: ` para documentos y `query: ` para consultas, y aplica mean pooling + normalización L2. Los 6.000 documentos requieren calcular sus vectores una vez; posteriormente la consola solo calcula la consulta.\n\n**Ejemplo para emular:** prueba `mantenimieto de aeronavess`. BM25 sin corrección puede perder términos. La opción RapidFuzz puede sugerir `mantenimiento de aeronaves` si el vocabulario y el umbral lo permiten. Compara rankings antes y después de aplicar una sugerencia, sin dar por hecho que la corrección mejora la pertinencia."},{"kind":"md","source":"## ETAPA 3 · Construir el motor semántico E5\n\n**De dónde sale el modelo:** [intfloat/multilingual-e5-small](https://huggingface.co/intfloat/multilingual-e5-small), descargado por SentenceTransformers. Este modelo produce **384 dimensiones**.\n\n**¿Qué hace?** Texto → tokenizer → encoder contextual → **mean pooling** (media sobre los tokens válidos) → vector fijo → normalización L2.\n\n**Importante:** el documento se procesa con prefijo *passage:* y la pregunta con *query:*. No mezcles vectores de modelos distintos. La matriz se guarda temporalmente para no recalcular cada búsqueda. Recalcular embeddings para otro corpus es imprescindible.\n\n**¿Qué significa pooling?** Las salidas del encoder son vectores por token; sumas sus componentes válidos y divides por el número de tokens válidos. El padding no cuenta. No es un promedio del texto literal.\n**Para 6.000 documentos:** los embeddings de 384 dimensiones ocupan unos 8,8 MiB en `float32`, sin contar el modelo ni PyTorch. La primera inferencia puede tomar varios minutos según el equipo. Al repetir consultas se calcula solo el vector de la pregunta. La caché identifica el corpus, el modelo y el límite de tokens; si reinicias Colab puede perderse. El máximo predeterminado de 256 tokens acelera el ejemplo, pero trunca documentos largos: para producción evalúa chunking o utiliza 512 tokens."},{"kind":"code","source":"#@title 4. Calcula embeddings E5 · modelo, pooling y caché\nimport os\nfrom sentence_transformers import SentenceTransformer\nMODEL_NAME=\"intfloat/multilingual-e5-small\"\nprint(\"Fuente del modelo: https://huggingface.co/intfloat/multilingual-e5-small\")\nmodelo=SentenceTransformer(MODEL_NAME)\n# Para 6.000 documentos la inferencia inicial puede durar minutos.\nimport torch\ndispositivo=\"cuda\" if torch.cuda.is_available() else \"cpu\"\nMAX_TOKENS_E5 = 256 #@param [256,512] {type:\"raw\"}\nmodelo.max_seq_length=int(MAX_TOKENS_E5)\nbatch_size=64 if dispositivo==\"cuda\" else 24\nprint(\"Dispositivo:\",dispositivo,\"· documentos:\",len(corpus),\"· máximo tokens:\",MAX_TOKENS_E5)\nprint(\"Si el texto es más largo se trunca. Para producción evalúa chunking y calidad.\")\ntextos=[\"passage: \"+str(t) for t in corpus[\"texto_busqueda\"]]\nconfig_embedding=MODEL_NAME+\"|max_tokens=\"+str(MAX_TOKENS_E5)\nruta_cache=os.path.join(os.getcwd(),\"s09_embeddings_\"+hashlib.sha256(config_embedding.encode()).hexdigest()[:8]+\"_\"+CORPUS_HUELLA[:18]+\".npy\")\ninicio=time.perf_counter()\nif os.path.exists(ruta_cache):\n    embeddings=np.load(ruta_cache)\n    if embeddings.shape!=(len(corpus),384):\n        os.remove(ruta_cache)\n        embeddings=modelo.encode(textos,batch_size=batch_size,normalize_embeddings=True,show_progress_bar=True)\n        np.save(ruta_cache,embeddings)\nelse:\n    embeddings=modelo.encode(textos,batch_size=batch_size,normalize_embeddings=True,show_progress_bar=True)\n    os.makedirs(os.path.dirname(ruta_cache),exist_ok=True)\n    np.save(ruta_cache,embeddings)\nembeddings=np.asarray(embeddings,dtype=np.float32)\nprint(\"Embeddings:\",embeddings.shape,\"· segundos:\",round(time.perf_counter()-inicio,2))\nprint(\"Memoria matriz:\",round(embeddings.nbytes/1024**2,2),\"MiB; modelo/PyTorch requieren memoria adicional.\")\nprint(\"Reejecutar la consulta no recalcula los 6.000 documentos.\")\nprint(\"Norma del primer vector:\",round(float(np.linalg.norm(embeddings[0])),4))\nassert embeddings.shape==(len(corpus),384)"},{"kind":"code","source":"#@title 5. Recupera por significado sobre los mismos documentos\ndef embedding_consulta(consulta):\n    if not str(consulta).strip(): raise ValueError(\"Escribe una consulta.\")\n    return modelo.encode([\"query: \"+str(consulta)],normalize_embeddings=True)[0]\ndef buscar_semantico_local(consulta,k=5,entidad=None):\n    q=embedding_consulta(consulta)\n    scores=embeddings @ q\n    candidatos=np.arange(len(corpus))\n    if entidad: candidatos=candidatos[corpus[\"entidad\"].eq(entidad).to_numpy()]\n    orden=candidatos[np.argsort(-scores[candidatos],kind=\"stable\")[:max(0,int(k))]]\n    data=corpus.iloc[orden][[\"id_proceso\",\"nombre_proceso\",\"descripcion\",\"entidad\",\"url_secop\"]].copy()\n    data[\"score_semantico\"]=scores[orden]\n    return data.reset_index(drop=True)\ndisplay(buscar_semantico_local(consulta_prueba,3)[[\"nombre_proceso\",\"score_semantico\"]])\nprint(\"El coseno entre vectores normalizados mide cercanía geométrica: no probabilidad.\")"},{"kind":"code","source":"#@title Laboratorio ortográfico completo: medir cambios en BM25 y E5\nprueba_bien = \"mantenimiento de aeronaves\"\nprueba_error = \"mantenimieto de aeronavess\"\nprueba_sugerida, correcciones_prueba = sugerir_correcciones(prueba_error)\nexperimento=[]\nreferencia_bm25=set(buscar_lexical(prueba_bien,5)[\"id_proceso\"].astype(str))\nreferencia_e5=set(buscar_semantico_local(prueba_bien,5)[\"id_proceso\"].astype(str))\nfor etiqueta,consulta in [(\"Bien escrita\",prueba_bien),(\"Con errores\",prueba_error),(\"Sugerida\",prueba_sugerida)]:\n    bm=buscar_lexical(consulta,5)\n    e5=buscar_semantico_local(consulta,5)\n    experimento.append({\n        \"versión\":etiqueta,\n        \"consulta\":consulta,\n        \"BM25 coincidencias\":len(bm),\n        \"BM25 Top-5 en común con correcta\":len(referencia_bm25 & set(bm[\"id_proceso\"].astype(str))),\n        \"E5 Top-5 en común con correcta\":len(referencia_e5 & set(e5[\"id_proceso\"].astype(str))),\n    })\ndisplay(pd.DataFrame(experimento))\nprint(\"Sugerencias de RapidFuzz:\",correcciones_prueba or \"ninguna\")\nprint(\"Compartir resultados entre rankings no demuestra relevancia: hace falta revisión humana.\")\nprint(\"Repite el experimento con una falta ortográfica inventada en tu propio sector.\")"},{"kind":"md","source":"## ETAPA 4 · Construir el motor híbrido\n\n**Por qué combinar:** un número de radicado o una marca puede favorecer BM25; una paráfrasis puede favorecer E5. Ninguno garantiza relevancia. RRF utiliza la posición relativa de los documentos en cada lista sin mezclar scores de escalas diferentes.\n\n**Reproducción en otro dominio:** mantén los pasos, ejecuta una consulta del nuevo negocio y compara el ranking resultante con juicios humanos. Si cambias el modelo, regenera embeddings y registra su nombre."},{"kind":"code","source":"#@title 6. Fusiona BM25 y E5 con RRF (combina posiciones, no scores)\ndef rrf_fusion(df_lex,df_sem,rank_constant=60):\n    acumulado={}\n    for fuente,tabla in [(\"BM25\",df_lex),(\"E5\",df_sem)]:\n        for posicion,r in enumerate(tabla.to_dict(\"records\"),start=1):\n            identificador=str(r[\"id_proceso\"])\n            if identificador not in acumulado:\n                acumulado[identificador]={k:r[k] for k in [\"id_proceso\",\"nombre_proceso\",\"descripcion\",\"entidad\",\"url_secop\"]}\n                acumulado[identificador].update(rrf=0.0,fuentes=[])\n            acumulado[identificador][\"rrf\"]+=1/(rank_constant+posicion)\n            acumulado[identificador][\"fuentes\"].append(f\"{fuente}#{posicion}\")\n    columnas=[\"id_proceso\",\"nombre_proceso\",\"descripcion\",\"entidad\",\"url_secop\",\"rrf\",\"fuentes\"]\n    if not acumulado:return pd.DataFrame(columns=columnas)\n    return pd.DataFrame(acumulado.values()).sort_values([\"rrf\",\"id_proceso\"],ascending=[False,True]).reset_index(drop=True)\nRRF_CONSTANT = 60\ndemo_lex=buscar_lexical(consulta_prueba,10)\ndemo_e5=buscar_semantico_local(consulta_prueba,10)\ndemo_rrf=rrf_fusion(demo_lex,demo_e5,RRF_CONSTANT)\ndisplay(demo_rrf[[\"nombre_proceso\",\"rrf\",\"fuentes\"]].head(5))\nprint(\"RRF premia aparecer bien posicionado en varios motores.\")"},{"kind":"md","source":"## ETAPA 5 · Comprobar conceptos antes de utilizar la consola\n\nSelecciona una opción en cada pregunta y pulsa comprobar. Son actividades de práctica; no hay LMS ni nota automática."},{"kind":"code","source":"#@title Comprueba qué aprendiste (decisiones cerradas)\nimport ipywidgets as widgets\nfrom IPython.display import display\npreguntas=[\n (\"¿Qué necesitas al cambiar de SECOP a PQRS?\",[\"Entrenar siempre otro LLM\",\"Identificar ID, texto y metadatos\",\"Copiar el enlace LMS\"],1,\n  \"El mismo pipeline funciona si normalizas un CSV propio y documentas sus columnas.\"),\n (\"¿Qué devuelve BM25?\",[\"Cercanía aprendida por E5\",\"Puntuación lexical basada en términos\",\"Probabilidad de contrato relevante\"],1,\n  \"BM25 utiliza la evidencia de tokens; no estima probabilidad de relevancia.\"),\n (\"¿Para qué sirve mean pooling?\",[\"Resumir vectores contextuales de tokens válidos\",\"Ordenar contratos por fecha\",\"Eliminar metadatos\"],0,\n  \"El encoder produce vectores por token; pooling agrega sus componentes.\"),\n (\"¿Cuál es la evaluación legítima?\",[\"Comparar 0.92 E5 con BM25 14\",\"Juicios humanos comunes y Precision@k\",\"Asumir que Top-5 siempre es correcto\"],1,\n  \"La métrica depende de etiquetas de relevancia, no de puntajes internos.\")]\npselect=[]\nfor q,opts,ok,exp in preguntas:\n    print(q)\n    w=widgets.Dropdown(options=[(\"Selecciona\",None)]+[(text,j) for j,text in enumerate(opts)],value=None,\n                       layout=widgets.Layout(width=\"90%\"))\n    pselect.append(w)\n    display(w)\ndef revisar_preguntas(_):\n    for (q,opts,ok,exp),w in zip(preguntas,pselect):\n        print((\"✓\" if w.value==ok else \"×\"),q,\"→\",exp)\ncheck=widgets.Button(description=\"Comprobar respuestas\",button_style=\"success\")\ncheck.on_click(revisar_preguntas)\ndisplay(check)"},{"kind":"md","source":"## ETAPA 6 · Utiliza tu propio buscador y observa sus decisiones\n\n**No hemos saltado la construcción.** Precision@5 es un caso particular de Precision@k cuando k=5.  Ya viste cómo leer CSV, mapear columnas, tokenizar, calcular BM25, descargar E5, producir vectores, usar coseno y fusionar posiciones.\n\nAhora la consola utiliza **esas mismas funciones**. Cambia libremente las consultas, el grupo y Top-k. Cada tarjeta muestra texto fuente, score y URL si existe.\n\n**Demostración:**\n1. Realiza una búsqueda textual; inspecciona coincidencias y posibles falsos positivos.\n2. Reformula la necesidad con sinónimos; compara qué recupera E5.\n3. Marca cada candidato único **sí/no relevante** y calcula Precision@k para BM25, E5 y RRF.\n4. Descarga el JSON: incluye fuente, mapeo, modelo, huella del corpus, parámetros, resultados, juicios y métricas.\n\n**Sin usuario LMS:** nada se envía a terceros para registrar una nota. Los modelos se descargan y ejecutan dentro de Colab; la evidencia se guarda localmente. La fuente y el modelo sí pueden requerir conexión a Internet.\n\n**Control de ortografía:** el modo predeterminado solo informa sugerencias. Selecciona «Aplicar sugerencias visibles» para ver qué efecto tiene sobre BM25, E5 y RRF. No hay autocorrección oculta. Para contrastar, repite exactamente la consulta con el modo «Sin corrección»."},{"kind":"code","source":"#@title 7. CONSOLA DE BÚSQUEDA · escribe, inspecciona, compara, evalúa\nimport ipywidgets as widgets\nfrom IPython.display import display, HTML, clear_output\nfrom html import escape\nfrom datetime import datetime, timezone\ntry:\n    from google.colab import output\n    output.enable_custom_widget_manager()\nexcept ImportError:\n    pass\n\nHISTORIAL_S09=[]\nestado_s09={\"consulta\":None,\"entidad\":None,\"k\":5,\"rankings\":None,\"juicios\":{},\n            \"comparacion\":None,\"latencias_ms\":{}}\ntabla_comparacion=pd.DataFrame()\nprecision_mia=None\nmi_consulta=\"\"\nconsulta_ui=widgets.Text(value=consulta_prueba,description=\"Necesidad:\",style={\"description_width\":\"initial\"},\n                         placeholder=\"Escribe cualquier búsqueda, no solo ejemplos...\",\n                         layout=widgets.Layout(width=\"98%\"))\nentidades=corpus[\"entidad\"].astype(str).value_counts().head(50).index.tolist()\nentidad_ui=widgets.Dropdown(options=[(\"Todas las entidades\",\"\")]+[(x,x) for x in entidades if x],\n                           description=\"Grupo:\",style={\"description_width\":\"initial\"})\nk_ui=widgets.Dropdown(options=[3,5,10],value=5,description=\"Top-k:\",style={\"description_width\":\"initial\"})\nortografia_ui=widgets.Dropdown(options=[\n (\"Sin corrección (BM25 literal)\", \"sin\"),\n (\"Sugerir cambios sin aplicarlos\", \"sugerir\"),\n (\"Aplicar sugerencias visibles\", \"aplicar\")],\n value=\"sugerir\",description=\"Ortografía:\",style={\"description_width\":\"initial\"},\n layout=widgets.Layout(width=\"65%\"))\nbtn_buscar=widgets.Button(description=\"Buscar en el corpus\",button_style=\"primary\",icon=\"search\",\n                          layout=widgets.Layout(width=\"200px\"))\nbtn_evaluar=widgets.Button(description=\"Calcular Precision@k\",button_style=\"success\",icon=\"check\")\nbtn_exportar=widgets.Button(description=\"Exportar expediente JSON\",icon=\"download\")\ndecision_ui=widgets.Dropdown(options=[(\"Selecciona una decisión\",None),(\"BM25\", \"BM25\"),(\"E5 semántico\",\"E5 semántico\"),\n (\"RRF híbrido\",\"RRF híbrido\"),(\"RRF + revisión manual\",\"RRF + revisión manual\")],\n description=\"Recomiendo:\",style={\"description_width\":\"initial\"})\nalternativa_ui=widgets.Dropdown(options=[(\"Selecciona alternativa\",None),(\"BM25\",\"BM25\"),(\"E5 semántico\",\"E5 semántico\"),\n (\"RRF híbrido\",\"RRF híbrido\"),(\"RRF + revisión manual\",\"RRF + revisión manual\")],\n description=\"Descarto:\",style={\"description_width\":\"initial\"})\nresultados_ui=widgets.Output()\nmetricas_ui=widgets.Output()\nexport_ui=widgets.Output()\njuicios_ui=widgets.VBox()\njuicios_controles={}\n\ndef tarjeta_resultado(r,pos,score_col,nombre):\n    titulo=escape(str(r.get(\"nombre_proceso\",\"\"))[:140])\n    texto=escape(str(r.get(\"descripcion\",\"\"))[:340]) or \"No hay descripción disponible en esta fuente.\"\n    id_doc=escape(str(r.get(\"id_proceso\",\"\")))\n    grupo=escape(str(r.get(\"entidad\",\"\"))[:90])\n    url=str(r.get(\"url_secop\",\"\")).strip()\n    enlace=('<a href=\"'+escape(url,quote=True)+'\" target=\"_blank\" rel=\"noopener noreferrer\">Consultar documento original ↗</a>'\n            if url.startswith((\"https://\",\"http://\")) else \"Fuente sin enlace individual\")\n    q=set(tokens(estado_s09[\"consulta\"]))\n    iguales=list(dict.fromkeys(t for t in tokens(str(r.get(\"nombre_proceso\",\"\"))+\" \"+str(r.get(\"descripcion\",\"\"))) if t in q))[:12]\n    coincidencias=\", \".join(iguales) if iguales else \"ninguna palabra idéntica\"\n    puntaje=float(r[score_col])\n    return ('<article style=\"border:1px solid #c7d7e5;border-radius:11px;background:#fff;margin:9px 0;padding:11px\">'\n      +f'<b>{pos}. {titulo}</b><p style=\"font-size:12px;color:#465673\">ID: {id_doc} · {grupo}</p>'\n      +f'<p style=\"font-size:13px;line-height:1.35\">{texto}</p>'\n      +f'<p style=\"font-size:12px\"><b>{nombre}: {puntaje:.4f}</b> · Palabras compartidas: {escape(coincidencias)}</p>'\n      +f'<p style=\"font-size:12px\">{enlace}</p></article>')\n\ndef buscar_s09(_=None):\n    global mi_consulta,top_lex,top_sem,top_hibrido,precision_mia,tabla_comparacion\n    with resultados_ui:\n        clear_output(wait=True)\n        q=consulta_ui.value.strip()\n        if not q:\n            print(\"Escribe una consulta para empezar.\");return\n        k=int(k_ui.value);grupo=entidad_ui.value or None\n        sugerida,cambios=sugerir_correcciones(q)\n        modo_ortografia=ortografia_ui.value\n        consulta_usada=sugerida if modo_ortografia==\"aplicar\" and cambios else q\n        t=time.perf_counter()\n        try:\n            top_lex=buscar_lexical(consulta_usada,max(10,3*k),grupo)\n            ms_lex=round((time.perf_counter()-t)*1000,1)\n            top_sem=buscar_semantico_local(consulta_usada,max(10,3*k),grupo)\n            ms_sem=round((time.perf_counter()-t)*1000-ms_lex,1)\n            top_hibrido=rrf_fusion(top_lex,top_sem,RRF_CONSTANT)\n        except Exception as exc:\n            print(\"No fue posible buscar:\",type(exc).__name__,str(exc));return\n        mi_consulta=q\n        rankings={\"BM25\":top_lex.head(k).copy(),\"E5 semántico\":top_sem.head(k).copy(),\n                  \"RRF híbrido\":top_hibrido.head(k).copy()}\n        estado_s09.update(consulta=q,entidad=grupo,k=k,rankings=rankings,juicios={},\n                          consulta_usada=consulta_usada,ortografia=modo_ortografia,\n                          sugerencias=cambios,\n                          comparacion=None,latencias_ms={\"BM25\":ms_lex,\"E5\":ms_sem})\n        precision_mia=None;tabla_comparacion=pd.DataFrame()\n        HISTORIAL_S09.append({\"consulta\":q,\"entidad\":grupo,\"top_k\":k,\"utc\":datetime.now(timezone.utc).isoformat()})\n        display(HTML(f'<h3>Resultados reales: {escape(q)}</h3><p><b>{len(corpus)} documentos</b>'\n              +f' · BM25 {ms_lex} ms · E5 {ms_sem} ms · Top-{k}</p>'\n              +'<p><b>BM25 = rank-bm25 (lexical); E5 = intfloat/multilingual-e5-small (384D); RapidFuzz = sugerencias ortográficas; RRF = fusión por posición.</b></p>'\n              +('<p style=\"padding:10px;background:#FFF3DD\"><b>Ortografía:</b> '\n                +escape(\"; \".join(a+\" → \"+b for a,b in cambios.items()))\n                +(\" · Sugerencias APLICADAS a BM25 y E5 (puedes desactivarlas).\"\n                   if modo_ortografia==\"aplicar\" else\n                   \" · Solo sugerencias; los rankings se calculan con el texto original.\")\n                +'</p>' if cambios else '<p>Sin sugerencias ortográficas seguras en el vocabulario del corpus.</p>')\n              +('<p><b>Consulta empleada para buscar:</b> '+escape(consulta_usada)+'</p>')\n              +'<p>Los scores no son probabilidades de relevancia. E5 ordena los candidatos aunque no sean pertinentes.</p>'))\n        paneles=[]\n        for nombre,col,color in [(\"BM25\",\"score_lexical\",\"#FFF0E2\"),\n                                 (\"E5 semántico\",\"score_semantico\",\"#E2F3F1\"),\n                                 (\"RRF híbrido\",\"rrf\",\"#ECE6FA\")]:\n            tabla=rankings[nombre]\n            cuerpo=\"\".join(tarjeta_resultado(r,i,col,nombre) for i,r in enumerate(tabla.to_dict(\"records\"),1))\n            paneles.append(widgets.HTML(value=f'<h3 style=\"padding:9px;background:{color}\">{nombre}</h3>'\n                     +(cuerpo or '<p>Sin resultados con este filtro. Prueba otra consulta.</p>'),\n                     layout=widgets.Layout(width=\"33%\",min_width=\"260px\")))\n        display(widgets.HBox(paneles,layout=widgets.Layout(width=\"100%\",flex_flow=\"row wrap\")))\n    dibujar_juicios()\n\ndef dibujar_juicios():\n    juicios_controles.clear()\n    if estado_s09[\"rankings\"] is None:return\n    todos=pd.concat([df[[\"id_proceso\",\"nombre_proceso\"]] for df in estado_s09[\"rankings\"].values()],\n                    ignore_index=True).drop_duplicates(\"id_proceso\")\n    filas=[widgets.HTML(\"<h3>Juicio de relevancia sobre documentos únicos</h3>\"\n                       \"<p>Lee el texto del resultado. El mismo juicio se utiliza en los tres rankings.</p>\")]\n    for r in todos.itertuples(index=False):\n        id_doc=str(r.id_proceso)\n        select=widgets.Dropdown(options=[(\"Sin evaluar\",None),(\"Sí relevante\",True),(\"No relevante\",False)],\n                                value=None,layout=widgets.Layout(width=\"170px\"))\n        juicios_controles[id_doc]=select\n        filas.append(widgets.HBox([widgets.HTML(escape(str(r.nombre_proceso)[:115]),\n                          layout=widgets.Layout(width=\"72%\")),select]))\n    juicios_ui.children=tuple(filas)\n    with metricas_ui:clear_output(wait=True)\n\ndef comparar_s09(_):\n    global precision_mia,tabla_comparacion\n    with metricas_ui:\n        clear_output(wait=True)\n        if estado_s09[\"rankings\"] is None:\n            print(\"Ejecuta una búsqueda primero.\");return\n        pendientes=[id_doc for id_doc,control in juicios_controles.items() if control.value is None]\n        if pendientes:\n            print(f\"Faltan {len(pendientes)} juicios de relevancia. No se inventan etiquetas.\");return\n        juicios={id_doc:control.value for id_doc,control in juicios_controles.items()}\n        filas=[]\n        for nombre,df in estado_s09[\"rankings\"].items():\n            ids=df[\"id_proceso\"].astype(str).tolist()\n            relevantes=sum(bool(juicios[id_doc]) for id_doc in ids)\n            filas.append({\"mecanismo\":nombre,\"documentos_devueltos\":len(ids),\n                          \"relevantes\":relevantes,\"precision_at_k\":round(relevantes/estado_s09[\"k\"],3)})\n        tabla_comparacion=pd.DataFrame(filas)\n        estado_s09[\"juicios\"]=juicios\n        estado_s09[\"comparacion\"]=filas\n        precision_mia=float(tabla_comparacion.loc[tabla_comparacion.mecanismo.eq(\"RRF híbrido\"),\"precision_at_k\"].iloc[0])\n        display(tabla_comparacion)\n        print(\"Evaluación formativa de UNA consulta; repetir con varias consultas y una referencia humana independiente.\")\n\ndef exportar_s09(_):\n    with export_ui:\n        clear_output(wait=True)\n        if estado_s09[\"rankings\"] is None:\n            print(\"Busca antes de exportar evidencia.\");return\n        elecciones={id_doc:control.value for id_doc,control in juicios_controles.items()}\n        completas=all(valor is not None for valor in elecciones.values())\n        relevantes=[id_doc for id_doc,valor in elecciones.items() if valor is True]\n        irrelevantes=[id_doc for id_doc,valor in elecciones.items() if valor is False]\n        opcion=decision_ui.value\n        descartada=alternativa_ui.value\n        if opcion and descartada and opcion==descartada:\n            print(\"La alternativa descartada debe ser distinta de la recomendada.\");return\n        documento={\"sesion\":9,\"modo\":\"reproducible_sin_lms\",\"utc\":datetime.now(timezone.utc).isoformat(),\n          \"defensible_results\":relevantes[:2],\"false_positive\":irrelevantes[0] if irrelevantes else None,\n          \"falso_positivo\":irrelevantes[0] if irrelevantes else None,\n          \"decision\":opcion,\"alternativa_descartada\":descartada,\n          \"limite\":\"Juicios formativos de una consulta; faltan referencia humana independiente, recall y otras consultas.\",\n          \"origen\":FUENTE_DESCRIPCION,\"mapeo_columnas\":MAPEO_COLUMNAS,\n          \"corpus\":{\"filas\":len(corpus),\"sha256\":CORPUS_HUELLA},\n          \"modelo_embedding\":MODEL_NAME,\"dimensiones\":int(embeddings.shape[1]),\n          \"metodo_lexical\":\"BM25Okapi\",\"metodo_vectorial\":\"E5 cosine\",\n          \"rrf_rank_constant\":RRF_CONSTANT,\"consulta\":estado_s09[\"consulta\"],\n          \"consulta_empleada\":estado_s09[\"consulta_usada\"],\n          \"modo_ortografia\":estado_s09[\"ortografia\"],\n          \"sugerencias_ortograficas\":estado_s09[\"sugerencias\"],\n          \"filtro_grupo\":estado_s09[\"entidad\"],\"top_k\":estado_s09[\"k\"],\n          \"tiempos_ms\":estado_s09[\"latencias_ms\"],\"historial_consultas\":HISTORIAL_S09,\n          \"resultados\":{nombre:tabla.to_dict(\"records\") for nombre,tabla in estado_s09[\"rankings\"].items()},\n          \"juicios\":elecciones,\"precision_at_k\":estado_s09[\"comparacion\"] if completas else None,\n          \"advertencia\":\"Evidencia local no identificada ni calificada en el LMS\"}\n        archivo=\"s09_evidencia_semantica.json\"\n        with open(archivo,\"w\",encoding=\"utf-8\") as file:\n            json.dump(documento,file,ensure_ascii=False,indent=2,\n                      default=lambda v:v.item() if hasattr(v,\"item\") else str(v))\n        print(\"Expediente guardado:\",archivo)\n        if not completas:print(\"Pendientes juicios; no se inventa Precision@k.\")\n        try:\n            from google.colab import files\n            files.download(archivo)\n        except ImportError:\n            print(\"Archivo disponible en el directorio de trabajo.\")\nbtn_buscar.on_click(buscar_s09)\nbtn_evaluar.on_click(comparar_s09)\nbtn_exportar.on_click(exportar_s09)\ndisplay(widgets.VBox([widgets.HTML('<h2>🔎 Consola de búsqueda y evaluación</h2>'\n    '<p>Busca cualquier necesidad en el corpus que elegiste al principio. Sin credenciales LMS.</p>'),\n    consulta_ui,widgets.HBox([entidad_ui,k_ui,btn_buscar]),\n    widgets.HBox([ortografia_ui]),\n    resultados_ui,juicios_ui,btn_evaluar,metricas_ui,decision_ui,alternativa_ui,btn_exportar,export_ui]))\nbuscar_s09()"},{"kind":"md","source":"## ETAPA 7 · Repite el experimento en otro contexto\n\n**Reto A · Transferencia operativa (15 minutos):**\n\n1. Genera un CSV pequeño con la celda siguiente o carga un CSV propio no confidencial.\n2. Vuelve a ETAPA 1 y elige **Subir CSV** o **CSV desde URL**.\n3. Vuelve a ETAPA 1 (mapeo): cambia el ID, título, texto, grupo y enlace. Revisa la vista previa.\n4. Vuelve a ejecutar ETAPA 2 (BM25), ETAPA 3 (E5, ahora con embeddings del nuevo corpus) y ETAPA 4 (RRF).\n5. Abre ETAPA 6, escribe una consulta específica de ese sector y compara los resultados.\n6. Descarga el JSON para que otra persona pueda identificar datos, modelo, parámetros y juicios.\n\n**Reto B · Comprobación cerrada:** si cargas una base de tickets, ¿debes cambiar necesariamente el algoritmo de BM25 y la fórmula RRF? **No**. Cambias fuente, mapeo y vuelves a calcular índices y embeddings. Si el desempeño es insuficiente, evalúas el modelo con evidencia antes de sustituirlo.\n\n**Condiciones para producción:** verificar licencias de uso, privacidad, calidad del corpus, cobertura, evaluación por múltiples consultas, tiempos, actualización e identificadores. Este ejercicio es una demostración didáctica, no un buscador institucional listo para desplegar."},{"kind":"code","source":"#@title Transferencia · genera una plantilla CSV para otro sector\nimport csv\nejemplos=[\n {\"id\":\"PQ-001\",\"titulo\":\"Demora en contestar solicitud\",\"texto\":\"La entidad tardó en responder una petición ciudadana\",\"grupo\":\"Servicio al ciudadano\",\"url\":\"\"},\n {\"id\":\"PQ-002\",\"titulo\":\"Falla en plataforma\",\"texto\":\"No se puede ingresar al portal de atención\",\"grupo\":\"Tecnología\",\"url\":\"\"},\n {\"id\":\"PQ-003\",\"titulo\":\"Reparación de servicio de red\",\"texto\":\"Se requiere mantener la conectividad de la sede\",\"grupo\":\"Tecnología\",\"url\":\"\"},\n {\"id\":\"PQ-004\",\"titulo\":\"Respuesta a derecho de petición\",\"texto\":\"El ciudadano solicita certificación de trámite\",\"grupo\":\"Servicio al ciudadano\",\"url\":\"\"}\n]\nruta_plantilla=\"plantilla_otro_contexto.csv\"\npd.DataFrame(ejemplos).to_csv(ruta_plantilla,index=False,encoding=\"utf-8-sig\")\nprint(\"Plantilla creada:\",ruta_plantilla)\ndisplay(pd.read_csv(ruta_plantilla).head())\nprint(\"Para usarla: vuelve a ETAPA 1, selecciona Subir CSV; en ETAPA 1 mapea:\")\nprint(\"ID = id · Título = titulo · Texto = texto · Grupo = grupo · URL = url\")\nprint(\"Ejecuta luego BM25, E5, RRF y consola. El ejemplo tiene solo 4 filas; no evalúes calidad de producción.\")\ntry:\n    from google.colab import files\n    # Descarga voluntaria: no forzar ventanas emergentes al iniciar.\nexcept ImportError:\n    pass"},{"kind":"md","source":"## ETAPA 8 · Profundización opcional: chunking y MongoDB Atlas\n\n**Chunking:** con documentos largos conviene recuperar fragmentos y mantener su ID documental. La demostración siguiente divide por palabras, no reproduce un tokenizer de producción. Para otro dominio evalúa tamaño/overlap y si el chunk permite contestar la pregunta.\n\n**MongoDB Atlas** es un sistema posible para almacenar vectores, metadatos e índice ANN; no es necesario para la búsqueda local ni para la exportación de evidencias. Si deseas practicar Atlas necesitarás credenciales de **tu propia base**, no del LMS. Todo lo previo se puede completar sin ese servicio."},{"kind":"md","source":"### ¿Dónde se ejecutan los componentes?\n\n- **Pandas:** lee y limpia el CSV.\n- **rank-bm25:** prepara el índice lexical en memoria.\n- **SentenceTransformers / multilingual-e5-small:** descarga el modelo y calcula embeddings de consulta/documento.\n- **NumPy:** calcula productos punto (equivalentes a coseno cuando los vectores están normalizados).\n- **RRF:** fusiona posiciones de los dos rankings sin sumar scores incompatibles.\n- **ipywidgets:** presenta controles, tarjetas de resultados, juicios y botones.\n- **JSON:** conserva la huella y configuración de un experimento reproducible.\n\nPara escalar, sustituirías los arrays en memoria por almacenamiento persistente, indexación ANN, API, control de acceso y actualización de documentos. **La lógica conceptual del pipeline y la evaluación sigue siendo la misma.**"},{"kind":"code","source":"#@title OPCIONAL · Comparar chunks y relaciones con E5\ndef chunk_palabras(texto,size=25,overlap=5):\n    if size<1 or overlap<0 or overlap>=size: raise ValueError(\"size debe superar overlap.\")\n    palabras=str(texto).split()\n    if not palabras: return []\n    resultado=[]\n    for inicio in range(0,len(palabras),size-overlap):\n        parte=palabras[inicio:inicio+size]\n        if not parte:break\n        resultado.append(\" \".join(parte))\n        if inicio+size>=len(palabras):break\n    return resultado\nfragmentos=chunk_palabras(str(corpus.iloc[0][\"texto_busqueda\"]),size=25,overlap=5)\ndisplay(pd.DataFrame({\"numero_chunk\":range(1,len(fragmentos)+1),\"texto\":fragmentos}))\nif fragmentos:\n    vec_chunks=modelo.encode([\"passage: \"+x for x in fragmentos],normalize_embeddings=True)\n    similitudes=vec_chunks @ embedding_consulta(consulta_prueba)\n    ranking_chunks=pd.DataFrame({\"chunk\":fragmentos,\"score_coseno\":similitudes}).sort_values(\"score_coseno\",ascending=False)\n    display(ranking_chunks)\nprint(\"Cada chunk puede convertirse en una unidad recuperable; conservamos el ID del documento original.\")"},{"kind":"md","source":"### Atlas es una extensión, no un requisito\n\nLas dos celdas siguientes **no se ejecutan por defecto**. Si tienes una cuenta propia de MongoDB Atlas puedes persistir e indexar los embeddings ya calculados y observar `$vectorSearch`, ANN y ENN. Esto permite practicar operación a escala, pero no necesitas Atlas para construir el buscador, calificar resultados o exportar evidencia.\n\n**Importante:** no cargues datos sensibles a una instancia ajena ni pegues secretos en el código. La URI se solicita de forma oculta y solo cuando seleccionas `USAR_ATLAS=True`."},{"kind":"code","source":"#@title OPCIONAL · MongoDB Atlas: persistir, indexar y buscar con una instancia propia\nfrom getpass import getpass\nfrom pymongo import MongoClient, UpdateOne\nfrom pymongo.operations import SearchIndexModel\nUSAR_ATLAS = False #@param {type:\"boolean\"}\nINDEX_NAME=\"s09_vector_index\"\natlas_conectado=False\nlisto=False\nif USAR_ATLAS:\n    try:\n        uri=getpass(\"URI de TU instancia MongoDB Atlas (entrada oculta): \").strip()\n        if not uri:raise ValueError(\"URI vacía\")\n        client=MongoClient(uri,serverSelectionTimeoutMS=12000)\n        client.admin.command(\"ping\")\n        col=client[\"laboratorio_s09\"][\"documentos\"]\n        docs=[]\n        for i,r in corpus.iterrows():\n            docs.append(UpdateOne({\"_id\":str(r[\"id_proceso\"])},{\"$set\":{\n                \"titulo\":str(r[\"nombre_proceso\"]),\"texto\":str(r[\"descripcion\"]),\n                \"entidad\":str(r[\"entidad\"]),\"embedding\":embeddings[i].tolist(),\n                \"modelo\":MODEL_NAME}},upsert=True))\n        if docs:col.bulk_write(docs,ordered=False)\n        definicion=SearchIndexModel(name=INDEX_NAME,type=\"vectorSearch\",definition={\"fields\":[\n            {\"type\":\"vector\",\"path\":\"embedding\",\"numDimensions\":384,\"similarity\":\"cosine\"},\n            {\"type\":\"filter\",\"path\":\"entidad\"}]})\n        if INDEX_NAME not in {i.get(\"name\") for i in col.list_search_indexes()}:\n            col.create_search_index(model=definicion)\n        for _ in range(10):\n            info=list(col.list_search_indexes(INDEX_NAME))\n            if info and info[0].get(\"queryable\"):\n                listo=True;break\n            time.sleep(5)\n        atlas_conectado=True\n        print(\"Atlas:\", \"índice disponible\" if listo else \"índice en construcción; sigue con búsqueda local\")\n    except Exception as e:\n        print(\"Atlas no disponible; no afecta BM25/E5/RRF locales:\",type(e).__name__,str(e)[:200])\nelse:\n    print(\"Atlas omitido: no necesitas credenciales de ninguna base para completar la sesión.\")"},{"kind":"code","source":"#@title OPCIONAL · ANN vs ENN: consultar el índice en Atlas\ndef buscar_atlas_modo(consulta,k=5,modo=\"ann\",num_candidates=100,entidad=None):\n    if not (USAR_ATLAS and atlas_conectado and listo):\n        raise RuntimeError(\"El índice Atlas no está disponible. Utiliza la consola local.\")\n    q=embedding_consulta(consulta).tolist()\n    stage={\"$vectorSearch\":{\"index\":INDEX_NAME,\"path\":\"embedding\",\"queryVector\":q,\"limit\":int(k)}}\n    if modo==\"enn\":\n        stage[\"$vectorSearch\"][\"exact\"] = True\n    else:\n        stage[\"$vectorSearch\"][\"exact\"] = False\n        stage[\"$vectorSearch\"][\"numCandidates\"] = max(int(num_candidates),20*int(k))\n    if entidad:\n        stage[\"$vectorSearch\"][\"filter\"]={\"entidad\":entidad}\n    return pd.DataFrame(list(col.aggregate([stage,{\"$project\":{\n        \"_id\":1,\"titulo\":1,\"entidad\":1,\"score\":{\"$meta\":\"vectorSearchScore\"}}}])))\n\nif USAR_ATLAS and atlas_conectado and listo:\n    consulta=estado_s09[\"consulta\"] or consulta_prueba\n    try:\n        print(\"ANN (aproximada):\")\n        display(buscar_atlas_modo(consulta,5,\"ann\",100))\n        print(\"ENN (exacta):\")\n        display(buscar_atlas_modo(consulta,5,\"enn\"))\n        print(\"Compara la identidad de vecinos y mide latencia en una ejecución repetible; no la infieras del score.\")\n    except Exception as e:\n        print(\"Atlas opcional no terminó:\",type(e).__name__)\nelse:\n    print(\"Ejercicio opcional no activado; la búsqueda local ya es plenamente funcional.\")"},{"kind":"md","source":"## Cierre · Lo que sabes replicar\n\nComprendes el camino de un documento desde su CSV hasta un ranking evaluado: origen → mapeo → tokens → BM25 → encoder/pooling E5 → similitud → RRF → relevancia humana → Precision@k → evidencia.\n\n**Tres afirmaciones que deberías poder comprobar:** (1) coseno no es probabilidad; (2) ranking no equivale a pertinencia; (3) cambiar de sector exige mapear columnas y recalcular embeddings, pero no necesariamente escribir otro buscador desde cero.\n\n**Conexión con S10:** al incorporar imagen, audio o video, primero necesitas ETL, extracción de texto o características y trazabilidad de origen antes de indexar."}]''')

def build_cells():
    """Recorrido autónomo. El login LMS nunca es un prerrequisito."""
    return [md(x["source"]) if x["kind"]=="md" else code(x["source"]) for x in CELLS]

def build_notebook():
    return {
        "nbformat": 4,
        "nbformat_minor": 5,
        "metadata": {
            "kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
            "language_info": {"name": "python", "version": "3.10.0"},
        },
        "cells": build_cells(),
    }

if __name__ == "__main__":
    path = Path(__file__).resolve().parents[1] / OUTPUT
    path.write_text(json.dumps(build_notebook(), ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    print(path)
